CREATE TABLE bracel_files(id uuid PRIMARY KEY,scope text NOT NULL,object_id uuid NOT NULL UNIQUE,name text NOT NULL,size bigint NOT NULL,sha256 text NOT NULL,content_type text NOT NULL,status text NOT NULL DEFAULT 'pending',expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '1 hour',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(status IN ('pending','uploaded','available','deleted'))); CREATE INDEX bracel_files_cleanup ON bracel_files(status,expires_at); CREATE TABLE bracel_attachments(scope text NOT NULL,resource uuid NOT NULL,file_id uuid NOT NULL REFERENCES bracel_files(id),PRIMARY KEY(scope,resource,file_id));